("`timescale 1ns/1ps
// @latency 9
module iterative_divider_core #(
    parameter WIDTH = 8
) (
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] dividend,
    input wire [WIDTH-1:0] divisor,
    input wire in_valid,
    output wire in_ready,
    output wire [WIDTH-1:0] quotient,
    output wire [WIDTH-1:0] remainder,
    output wire out_valid,
    input wire out_ready
);

    localparam COUNT_WIDTH = $clog2(WIDTH + 1);

    reg busy;
    reg out_valid_reg;
    reg [WIDTH-1:0] dividend_reg;
    reg [WIDTH-1:0] divisor_reg;
    reg [WIDTH-1:0] quotient_work;
    reg [WIDTH:0] remainder_work;
    reg [COUNT_WIDTH-1:0] iteration;

    reg [WIDTH-1:0] quotient_reg;
    reg [WIDTH-1:0] remainder_reg;

    wire signed [WIDTH+1:0] partial_extended;
    wire signed [WIDTH+1:0] divisor_extended;
    wire signed [WIDTH+1:0] shifted_remainder;
    wire signed [WIDTH+1:0] next_partial;
    wire signed [WIDTH+1:0] final_partial;
    wire [WIDTH-1:0] next_quotient;

    assign partial_extended = {remainder_work[WIDTH], remainder_work};
    assign divisor_extended = {2'b00, divisor_reg};
    assign shifted_remainder =
        (partial_extended <<< 1) |
        {{WIDTH+1{1'b0}}, quotient_work[WIDTH-1]};
    assign next_partial = shifted_remainder +
        (remainder_work[WIDTH] ? divisor_extended : -divisor_extended);
    assign next_quotient =
        (quotient_work << 1) | ~next_partial[WIDTH+1];
    assign final_partial = next_partial[WIDTH+1]
        ? next_partial + divisor_extended
        : next_partial;

    assign in_ready = !busy && !out_valid_reg;
    assign out_valid = out_valid_reg;
    assign quotient = quotient_reg;
    assign remainder = remainder_reg;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            out_valid_reg <= 1'b0;
            dividend_reg <= {WIDTH{1'b0}};
            divisor_reg <= {WIDTH{1'b0}};
            quotient_work <= {WIDTH{1'b0}};
            remainder_work <= {(WIDTH+1){1'b0}};
            iteration <= {COUNT_WIDTH{1'b0}};
            quotient_reg <= {WIDTH{1'b0}};
            remainder_reg <= {WIDTH{1'b0}};
        end else if (busy) begin
            quotient_work <= next_quotient;
            remainder_work <= next_partial[WIDTH:0];

            if (iteration == WIDTH - 1) begin
                busy <= 1'b0;
                out_valid_reg <= 1'b1;
                quotient_reg <= next_quotient;
                remainder_reg <= final_partial[WIDTH-1:0];
            end else begin
                iteration <= iteration + 1'b1;
            end
        end else if (out_valid_reg) begin
            if (out_ready)
                out_valid_reg <= 1'b0;
        end else if (in_valid && in_ready) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            quotient_work <= dividend;
            remainder_work <= {(WIDTH+1){1'b0}};
            iteration <= {COUNT_WIDTH{1'b0}};
            busy <= 1'b1;
        end
    end

endmodule", '(no message IDs)', 'Testbench failures:
